@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Loyality Hub Membership'
@Metadata.ignorePropagatedAnnotations: true
define  view entity ZLH_R_Membership
  as select from zlh_membership
  association to parent ZLH_R_BusinessPartner as _BP on $projection.BusinessPartner = _BP.SoldToParty
  composition [0..*] of ZLH_R_CATEGORY        as _Category
  
//  association [1] to ZLH_I_MembershipStatusVH as _StatusVH on $projection.MembershipStatus = _StatusVH.value_low
{
  key membershipid     as MembershipID,
      business_partner as BusinessPartner,
      member_since     as MemberSince,
      membership_enddate as MembershipEndDate,
//      @ObjectModel.text.association: '_StatusVH'
//      @ObjectModel.text.element:[ 'StatusText' ]
//      @Consumption.valueHelpDefinition:[{ entity:{name: 'ZLH_I_MembershipStatusVH', element: 'value_low' }, distinctValues: true }]
      membership_status as MembershipStatus,
      created_by       as CreatedBy,
      created_on       as CreatedOn,
      last_changedat   as LastChangedat,
      last_changedby   as LastChangedby,
//      _StatusVH.text as StatusText,
      _BP,
      _Category
//      _StatusVH
}
